void ck(bool ok,const std::string&n,int&bad,int&total){++total;std::cout<<"test="<<n<<" result="<<(ok?"PASS":"FAIL")<<'\n';if(!ok)++bad;}
bool same(const void*a,const void*b,size_t n){return std::memcmp(a,b,n)==0;}
